css:
.resume{--page-width: 210mm;
      --page-height: 297mm;
      --primary: #1A3B47;      
      --accent: #D94F2B;      
      --body-text: #2E2E2C;
      --muted: #5C5C5A;
      --bg-light: #F9F7F4;
      --divider: #D2CFC7;
      --safe-white: #FFFFFF;
      --geometric-light: #F0E9DF;}
.resume{width: var(--page-width);
      min-height: var(--page-height);
      background: var(--safe-white);
      box-shadow: 0 12px 28px rgba(0,0,0,0.15);
      display: flex;
      flex-direction: column;
      position: relative;
      overflow: hidden;
      border-radius: 2px;
      margin-bottom: 2rem;}
.geometric-decor{position: absolute;
      top: 0;
      right: 0;
      width: 280px;
      height: 280px;
      background: radial-gradient(circle at 100% 0%, rgba(217,79,43,0.18) 0%, rgba(26,59,71,0.06) 70%);
      clip-path: polygon(100% 0, 0% 0, 100% 100%);
      z-index: 0;
      pointer-events: none;}
.geometric-line{position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: repeating-linear-gradient(45deg, transparent, transparent 18px, rgba(217,79,43,0.05) 18px, rgba(217,79,43,0.05) 20px);
      z-index: 0;
      pointer-events: none;}
.accent-block{position: absolute;
      bottom: 0;
      left: 0;
      width: 180px;
      height: 12px;
      background: var(--accent);
      z-index: 0;}
.resume-content{position: relative;
      z-index: 2;
      padding: 1.6cm 2cm 1.4cm 2cm;
      display: flex;
      flex-direction: column;
      gap: 1.2rem;
      background: transparent;}
.resume h1, .resume h2, .resume h3, .resume p, .resume li, .resume div, .resume span{font-weight: normal;}
.header{display: flex;
      flex-direction: column;
      border-bottom: 3px solid var(--primary);
      padding-bottom: 1rem;
      margin-bottom: 0.5rem;}
.name{font-size: 44pt;
      font-family: 'Arial', 'Helvetica Neue', '思源黑体', sans-serif;
      font-weight: 700;
      color: var(--primary);
      letter-spacing: 1px;
      line-height: 1.1;
      margin-bottom: 0.2rem;}
.title{font-size: 14pt;
      font-weight: 400;
      color: var(--accent);
      letter-spacing: 2px;
      text-transform: uppercase;
      font-family: 'Arial', 'Helvetica Neue', sans-serif;
      margin-top: 0.1rem;}
.contact-row{display: flex;
      flex-wrap: wrap;
      gap: 1.8rem;
      margin-top: 1rem;
      font-size: 10.5pt;
      color: var(--muted);
      align-items: center;}
.contact-item{display: flex;
      align-items: center;
      gap: 0.3rem;}
.icon{display: inline-block;
      width: 16px;
      text-align: center;
      font-weight: 500;
      color: var(--primary);}
.section-title{font-size: 13pt;
      font-weight: 700;
      color: var(--primary);
      text-transform: uppercase;
      letter-spacing: 1.5px;
      border-bottom: 1.8px solid var(--divider);
      padding-bottom: 0.3rem;
      margin-bottom: 0.8rem;
      margin-top: 0.3rem;
      font-family: 'Arial', 'Helvetica Neue', sans-serif;}
.experience-item{margin-bottom: 1.1rem;}
.exp-header{display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;
      margin-bottom: 0.25rem;}
.company{font-weight: 700;
      font-size: 12pt;
      color: var(--body-text);}
.role{font-weight: 600;
      font-size: 11pt;
      color: var(--primary);
      margin-left: 0.5rem;
      font-style: normal;}
.date{font-size: 10pt;
      color: var(--muted);
      font-weight: 400;
      white-space: nowrap;}
.description{margin-top: 0.25rem;
      padding-left: 1.2rem;
      list-style-type: none;}
.description li{font-size: 10pt;
      color: var(--body-text);
      margin-bottom: 0.3rem;
      position: relative;
      padding-left: 0.8rem;}
.description li::before{content: "•";
      position: absolute;
      left: 0;
      color: var(--accent);
      font-weight: bold;
      font-size: 10pt;}
.skills-container{display: flex;
      flex-wrap: wrap;
      gap: 0.8rem 1.5rem;
      margin-top: 0.3rem;}
.skill-group{display: flex;
      flex-wrap: wrap;
      align-items: baseline;
      gap: 0.5rem;}
.skill-label{font-weight: 700;
      font-size: 10.5pt;
      color: var(--primary);}
.skill-tags{display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;}
.tag{font-size: 10pt;
      background: transparent;
      color: var(--body-text);
      border: 1px solid var(--divider);
      padding: 0.2rem 0.8rem;
      border-radius: 2px;
      font-weight: 400;
      background: var(--bg-light);}
.education-item{display: flex;
      justify-content: space-between;
      align-items: baseline;
      margin-bottom: 0.4rem;}
.school{font-weight: 700;
      font-size: 11pt;}
.degree{font-weight: 400;
      color: var(--muted);
      margin-left: 0.5rem;}
.resume hr{border: none;
      border-top: 1px solid var(--divider);
      margin: 0.5rem 0 0.8rem 0;}

.resume-title{font-size:9pt;letter-spacing:0.14em;color:#5C5C5A;margin-bottom:6px}.summary{font-size:10.5pt;color:var(--body-text);line-height:1.6}.misc-line{display:flex;gap:3rem;margin-top:0.2rem}.misc-line .misc-label{font-weight:700;font-size:10.5pt;color:var(--primary);margin-right:0.8rem}.lang{margin-right:8px}
